<script lang="ts">
    import {onMount,tick} from 'svelte';
    import {get} from 'svelte/store';
    import {location} from 'svelte-spa-router';
    import {musicViewState as musicState,musicCurrentLyric,musicOpen,musicConnection,musicBridgeError,musicLibrary,musicRequest,musicSettings,musicTransport,playMusic,refreshMusic,musicTime,musicWidgets,musicKey,favoriteMusic,type MusicWidgets,type MusicTrack} from './music';
    import {clickGuiVisible} from './clickGuiLifecycle';
    import {setTyping} from '../integration/rest';
    import MusicIcon from './MusicIcon.svelte';
    import MusicProgress from './MusicProgress.svelte';
    import {scaleFactor} from '../routes/clickgui/clickgui_store';
    import {ripple} from './motion';
    const savedLibrary=get(musicLibrary);
    let dialog:HTMLElement,search:HTMLInputElement,keyword=savedLibrary.keyword,page=savedLibrary.page,results:MusicTrack[]=savedLibrary.results,playlists:{id:number;name:string;trackCount:number;coverImgUrl?:string;subscribed?:boolean}[]=[];
    let lastSearchResults=results;
    let view='search',busy=false,message='',qr='',qrKey='',qrMessage='请使用网易云音乐 App 扫码',qrTimer:ReturnType<typeof setTimeout>,alive=true,requestEpoch=0;
    let viewportWidth=innerWidth,viewportHeight=innerHeight,playlistName='',playlistCover='';
    $: uiScale=Math.max(1,Math.min(2.5,viewportWidth/1000,Math.max($scaleFactor/2,viewportWidth/1920)));
    $: liked=new Set(state?.favoriteKeys??[]);
    $: heading=view==='favorites'?'本地收藏':view==='playlist'?playlistName:keyword?'搜索：'+keyword:'Tritium Music';
    let volumeDraft:number|undefined,volumeTimer:ReturnType<typeof setTimeout>;
    $: state=$musicState;
    $: lyric=$musicCurrentLyric;
    $: selectedView=!state?.provider?'choose':view;
    $: $clickGuiVisible,$location,closeIfHidden();
    function closeIfHidden(){if($location!=='/clickgui'||!$clickGuiVisible)musicOpen.set(false);}
    async function run(action:()=>Promise<void>){if(busy)return;busy=true;message='';try{await action();}catch(error){if(alive)message=error instanceof Error?error.message:'请求失败';}finally{if(alive)busy=false;}}
    function close(){musicOpen.set(false);}
    async function choose(provider:'netease'|'gd'){
        await run(async()=>{cancelQr();await musicSettings({provider});results=[];lastSearchResults=[];playlists=[];view=provider==='netease'&&!$musicState?.loggedIn?'login':'search';if(view==='login')await createQr();else{await tick();search?.focus();}});
    }
    function cancelQr(){requestEpoch++;clearTimeout(qrTimer);qrKey='';qr='';}
    async function createQr(){
        cancelQr();const epoch=requestEpoch;
        const data=await musicRequest<{key:string;url:string}>('/qr/new',{});if(!alive||epoch!==requestEpoch)return;
        const {default:QRCode}=await import('qrcode');if(!alive||epoch!==requestEpoch)return;
        qrKey=data.key;qr=await QRCode.toDataURL(data.url,{width:220,margin:2,errorCorrectionLevel:'M'});qrMessage='请使用网易云音乐 App 扫码';
        const poll=async()=>{if(!alive||epoch!==requestEpoch||view!=='login')return;
            try{const result=await musicRequest<{code:number}>('/qr/check',{key:qrKey});if(!alive||epoch!==requestEpoch)return;
                if(result.code===803){cancelQr();await refreshMusic();view='search';message='登录成功';void loadPlaylists();return;}
                qrMessage=result.code===800?'二维码已过期，请刷新':result.code===802?'扫码成功，请在手机确认':'等待扫码';if(result.code===800)return;
            }catch{qrMessage='登录检查失败，请刷新二维码';return;}
            qrTimer=setTimeout(poll,1800);
        };qrTimer=setTimeout(poll,1800);
    }
    async function searchSongs(next=1){if(!keyword.trim()||!state?.provider)return;await run(async()=>{cancelQr();view='search';page=next;results=await musicRequest<MusicTrack[]>('/search',{keyword,page});lastSearchResults=results;});}
    async function loadPlaylists(){try{playlists=await musicRequest('/playlists');}catch(error){message=String(error);}}
    async function showPlaylists(){await run(async()=>{cancelQr();await loadPlaylists();view='playlists';});}
    async function showFavorites(){await run(async()=>{cancelQr();results=await musicRequest<MusicTrack[]>('/favorites');view='favorites';});}
    async function favorite(song:MusicTrack){await run(async()=>{await favoriteMusic(song,!liked.has(musicKey(song)));if(view==='favorites')results=await musicRequest<MusicTrack[]>('/favorites');});}
    async function openPlaylist(id:number){await run(async()=>{results=await musicRequest('/playlist',{id:String(id)});const list=playlists.find(p=>p.id===id);playlistName=list?.name??'歌单';playlistCover=list?.coverImgUrl??'';view='playlist';});}
    function volume(value:number){volumeDraft=value;clearTimeout(volumeTimer);volumeTimer=setTimeout(()=>{void musicSettings({volume:value/100}).catch(error=>message=String(error));},80);}
    function keydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();close();}}
    onMount(()=>{if($musicState?.loggedIn)void loadPlaylists();dialog.focus();void setTyping(true).catch(()=>{});window.addEventListener('keydown',keydown,true);return()=>{alive=false;musicLibrary.set({keyword,page,results:lastSearchResults});cancelQr();clearTimeout(volumeTimer);if(volumeDraft!==undefined)void musicSettings({volume:volumeDraft/100}).catch(()=>{});window.removeEventListener('keydown',keydown,true);void setTyping(false).catch(()=>{});};});
</script>
<svelte:window bind:innerWidth={viewportWidth} bind:innerHeight={viewportHeight}/>
<div class="music-overlay">
<div class="music-panel" style:zoom={uiScale} style:width="{viewportWidth/uiScale-24}px" style:height="{Math.max(260,viewportHeight/uiScale-64)}px" style:top="52px" bind:this={dialog} role="dialog" aria-modal="true" aria-label="Tritium Music player" tabindex="-1">
    <aside class="sidebar">
        <form on:submit|preventDefault={()=>searchSongs()}><MusicIcon name="search" size={17}/><input bind:this={search} aria-label="搜索歌曲" bind:value={keyword} placeholder="搜索歌曲、歌手或专辑" maxlength="160"/><button class="search-submit" aria-label="搜索" type="submit" disabled={busy||!keyword.trim()}><MusicIcon name="search" size={16}/></button></form>
        <h1>Tritium Music</h1>
        <button class="nav-row" class:chosen={view==='search'} on:click={()=>{cancelQr();view='search';}}><MusicIcon name="home" size={17}/>主页</button>
        <button class="nav-row" class:chosen={view==='favorites'} on:click={showFavorites}><MusicIcon name="heart" size={17}/>本地收藏</button>
        {#if state?.provider==='netease'}<button class="section-label" aria-label="我的歌单" on:click={showPlaylists}>我的歌单</button><div class="playlist-nav">{#each playlists.filter(p=>!p.subscribed) as list}<button class="nav-row" on:click={()=>openPlaylist(list.id)}><MusicIcon name="playlist" size={16}/><span>{list.name}</span></button>{/each}
        {#if playlists.some(p=>p.subscribed)}<p class="section-label">收藏歌单</p>{#each playlists.filter(p=>p.subscribed) as list}<button class="nav-row" on:click={()=>openPlaylist(list.id)}><MusicIcon name="playlist" size={16}/><span>{list.name}</span></button>{/each}{/if}</div>{/if}
        <div class="sidebar-bottom"><MusicIcon name="user" size={24}/><span>{state?.profile||(state?.provider==='gd'?'GD 音乐台':'未登录')}</span>{#if state?.provider==='netease'&&!state.loggedIn}<button on:click={()=>{view='login';void run(createQr);}}>扫码登录</button>{/if}</div>
    </aside>
    <div class="workspace"><header><span>Tritium Music</span><div class="lyric">{lyric}</div><button aria-label="音乐设置" on:click={()=>{cancelQr();view='settings';}} use:ripple><MusicIcon name="gear"/></button><button aria-label="关闭音乐面板" on:click={close} use:ripple><MusicIcon name="close"/></button></header>
    <main>
    {#if $musicConnection!=='ready'}<div class="unavailable"><h2>音乐桥接尚未连接</h2><p>{$musicBridgeError||'请使用 OpaiBounceScript.js 1.4.2，并确认主题的 music 文件夹已经完整安装。替换后完全退出并重启游戏。'}</p><button on:click={()=>run(refreshMusic)}>重新连接</button></div>
    {:else if selectedView==='choose'||selectedView==='settings'}
        <div class="setup"><h2>{selectedView==='choose'?'选择音乐接入方式':'音乐设置'}</h2><p>之后可在这里重新选择。</p>
            <button class="provider" class:chosen={state?.provider==='netease'} on:click={()=>choose('netease')} disabled={busy} use:ripple><strong>官方网易云登录</strong><span>使用网易云 App 扫码，访问账号歌单与可播放曲目</span></button>
            <button class="provider" class:chosen={state?.provider==='gd'} on:click={()=>choose('gd')} disabled={busy} use:ripple><strong>免 VIP 接入 · GD 音乐台</strong><span>无需网易云登录，可播放范围由音乐来源决定</span></button>
            {#if state?.provider==='gd'}<label class="source">音乐源<select aria-label="音乐源" value={state.source} on:change={e=>run(()=>musicSettings({source:e.currentTarget.value}))}><option value="netease">网易云</option><option value="joox">JOOX</option><option value="bilibili">bilibili</option></select></label>{/if}
            {#if state?.loggedIn}<p>网易云：{state.profile}</p><button on:click={()=>run(async()=>{await musicRequest('/logout',{});await refreshMusic();})}>退出网易云登录</button>{/if}
            <p>音乐 HUD 与 3D 歌词模式请在 Tritium Music 模块的原生设置中调整。</p>
            {#if state?.provider}<button class="back" on:click={()=>view='search'}>返回播放器</button>{/if}
        </div>
    {:else if selectedView==='login'}<div class="login"><h2>网易云音乐扫码登录</h2>{#if qr}<img class="qr" src={qr} alt="网易云音乐登录二维码"/>{:else}<div class="qr placeholder">正在生成二维码…</div>{/if}<p role="status">{qrMessage}</p><button disabled={busy} on:click={()=>run(createQr)}>刷新二维码</button><button on:click={()=>{cancelQr();view='search';}}>稍后登录</button></div>
    {:else}
        <div class="library-header"><div class="hero-cover">{#if playlistCover&&view==='playlist'}<img src={playlistCover} alt="歌单封面" referrerpolicy="no-referrer"/>{:else if state?.track?.cover}<img src={state.track.cover} alt="当前专辑封面" referrerpolicy="no-referrer"/>{:else}<MusicIcon name={view==='favorites'?'heart':'note'} size={80}/>{/if}</div><div class="hero-text"><h2>{heading}</h2><p>{results.length} 首歌曲{view==='favorites'?' · 保存在本机，不同步到网易云账号':''}</p><p class="profile">{state?.profile||(state?.provider==='gd'?'GD 音乐台':'网易云音乐')}</p><div class="hero-actions"><button class="primary" disabled={!results.length||busy} on:click={()=>run(()=>playMusic(results,0))}><MusicIcon name="play" size={16}/>播放{view==='playlist'?'歌单':'全部'}</button>{#if view==='favorites'}<button on:click={()=>view='search'}>搜索歌曲</button>{/if}</div></div></div>
        <div class="results" aria-label="歌曲列表">{#if view==='playlists'}{#each playlists as list}<button class="playlist-row" on:click={()=>openPlaylist(list.id)}><MusicIcon name="playlist"/><span>{list.name}</span><small>{list.trackCount} 首</small></button>{/each}
        {:else}{#each results as song,i}<div class="song-row" class:active={state?.track&&musicKey(state.track)===musicKey(song)}><button class="song" on:click={()=>run(()=>playMusic(results,i))} aria-label="播放 {song.name}" use:ripple><span class="number">{i+1+(view==='search'?(page-1)*20:0)}</span><div class="song-cover">{#if song.cover}<img src={song.cover} alt="" referrerpolicy="no-referrer" loading="lazy" decoding="async"/>{:else}<MusicIcon name="note" size={22}/>{/if}</div><div class="song-text"><strong>{song.name}</strong><small>{song.artists.join(' / ')} · {song.album}</small></div><span class="song-time">{song.duration?musicTime(song.duration):'—:—'}</span></button><button class="favorite" class:liked={liked.has(musicKey(song))} aria-label={(liked.has(musicKey(song))?'取消收藏 ':'收藏 ')+song.name} aria-pressed={liked.has(musicKey(song))} disabled={busy} on:click={()=>favorite(song)}><MusicIcon name="heart" size={18}/></button></div>{:else}<div class="empty">{busy?'正在加载…':view==='favorites'?'还没有收藏歌曲，点击歌曲旁的爱心添加':'搜索并选择一首歌曲开始播放'}</div>{/each}{/if}</div>
        {#if view==='search'&&results.length}<div class="pages"><button disabled={busy||page===1} on:click={()=>searchSongs(page-1)}>上一页</button><span>{page}</span><button disabled={busy||results.length<20} on:click={()=>searchSongs(page+1)}>下一页</button></div>{/if}
    {/if}
    </main>
    {#if message||state?.error}<p class="error" role="status">{message||state?.error}</p>{/if}
    </div>
    <footer><div class="now-playing">{#if state?.track?.cover}<img src={state.track.cover} alt="播放中专辑封面" referrerpolicy="no-referrer"/>{:else}<div class="mini-cover"><MusicIcon name="note" size={24}/></div>{/if}<div><strong>{state?.track?.name??'尚未播放'}</strong><small>{state?.track?.artists.join(' / ')??'Tritium Music'}</small></div>{#if state?.track}<button class="favorite" class:liked={liked.has(musicKey(state.track))} aria-label="收藏当前歌曲" aria-pressed={liked.has(musicKey(state.track))} on:click={()=>favorite(state.track!)}><MusicIcon name="heart" size={19}/></button>{/if}</div>
    <div class="playback"><div class="transport"><button aria-label="上一首" disabled={!state?.track} on:click={()=>run(()=>musicTransport('previous'))} use:ripple><MusicIcon name="previous" size={20}/></button><button class="play" aria-label={state?.playing?'暂停':'播放'} disabled={!state?.track||state?.loading} on:click={()=>run(()=>musicTransport(state?.playing?'pause':'resume'))} use:ripple><MusicIcon name={state?.playing?'pause':'play'} size={22}/></button><button aria-label="下一首" disabled={!state?.track} on:click={()=>run(()=>musicTransport('next'))} use:ripple><MusicIcon name="next" size={20}/></button><button class:chosen={state?.repeatOne} aria-label="单曲循环" aria-pressed={state?.repeatOne??false} disabled={!state} on:click={()=>run(()=>musicSettings({repeatOne:!state?.repeatOne}))} use:ripple><MusicIcon name="repeat" size={19}/><small class="repeat-one">1</small></button></div>
        <MusicProgress duration={state?.track?.duration??0} seekable onSeek={value=>musicTransport('seek',value).catch(error=>{message=String(error);})}/></div>
        <label class="volume"><MusicIcon name="volume" size={19}/><input type="range" aria-label="音乐音量" min="0" max="100" value={volumeDraft??Math.round((state?.volume??.25)*100)} on:input={e=>volume(Number(e.currentTarget.value))} disabled={!state}/><span>{volumeDraft??Math.round((state?.volume??.25)*100)}%</span></label>
    </footer>
    <div class="credits">{#if state?.provider==='gd'}来源：<a href="https://music.gdstudio.xyz/" target="_blank" rel="noreferrer">GD音乐台 (music.gdstudio.xyz)</a> · CC BY-NC 4.0 · 仅供非商业学习{:else}基于 <a href="https://github.com/opai-client/tritium-music" target="_blank" rel="noreferrer">Tritium Music</a> · 网易云音乐{/if}</div>
</div></div>
<style>
.music-overlay{position:fixed;inset:0;z-index:100020;background:#0002;font:14px 'Google Sans','Opai CJK',sans-serif;color:#ededed}.music-panel{position:absolute;left:12px;display:grid;grid-template-columns:240px minmax(0,1fr);grid-template-rows:minmax(0,1fr) 76px 20px;overflow:hidden;border-radius:8px;background:#1e1e1e;box-shadow:var(--opai-hud-shadow);outline:none;box-sizing:border-box}.sidebar{grid-column:1;grid-row:1;display:flex;flex-direction:column;min-height:0;padding:20px 16px 12px;background:#242424bd}.sidebar form{display:flex;align-items:center;gap:5px;border:1px solid #5a5a5a;border-radius:7px;padding:3px 6px;flex:none}.sidebar input{min-width:0;width:100%;background:none;color:inherit;border:0;outline:none;font:inherit;padding:6px 0}.search-submit{padding:3px!important;background:none!important}.sidebar h1{font-size:14px;color:#999;font-weight:500;margin:16px 4px 8px}.nav-row{display:flex;align-items:center;gap:10px;background:none;text-align:left;width:100%;padding:10px 12px;flex:none}.nav-row span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nav-row.chosen{background:#ffffff0b;color:var(--accent-color)}.section-label{margin:12px 4px 4px;color:#999;background:none;padding:0;font-size:12px;text-align:left}.playlist-nav{flex:1;overflow:auto;min-height:0}.sidebar-bottom{display:flex;gap:10px;align-items:center;padding:12px 3px 0;margin-top:auto;font-size:13px}.sidebar-bottom span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis}.sidebar-bottom button{font-size:11px;padding:5px}.workspace{min-width:0;min-height:0;display:flex;flex-direction:column;grid-column:2;grid-row:1}.workspace header{height:38px;flex:none;display:flex;align-items:center;gap:8px;padding:0 12px;color:#888;font-size:12px}.workspace header>span{margin-right:auto}.workspace header .lyric{max-width:50%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.workspace header button{padding:4px;background:none}.workspace main{padding:12px 28px 16px;display:flex;fle